.ds-contact-action {
  display: inline-flex;
  min-block-size: 44px;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  padding: var(--space-2) var(--space-4);
  padding-inline: var(--space-4) var(--space-3);
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: var(--ink);
  color: var(--paper-bright);
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  line-height: 1.2;
  text-transform: uppercase;
  text-decoration: none;
  transition:
    background-color 160ms ease-out,
    color 160ms ease-out;
}
.ds-contact-action:hover,
.ds-contact-action:focus-visible {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--accent-ink);
}
.ds-contact-action:active {
  background: var(--text);
  border-color: var(--text);
  color: var(--bg);
}
.ds-contact-action .ds-editorial-arrow {
  inline-size: 0.9rem;
  block-size: 0.9rem;
}.ds-editorial-arrow {
  inline-size: 1.35rem;
  block-size: 1.35rem;
  flex: 0 0 auto;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.75;
  transition: transform 240ms cubic-bezier(0.16, 1, 0.3, 1);
}
a:is(:hover, :focus-visible) .ds-editorial-arrow,
button:is(:hover, :focus-visible) .ds-editorial-arrow {
  transform: translate(4px, -4px);
}.ds-contact-action:focus-visible { outline: 2px solid var(--ink); outline-offset: 4px; box-shadow: 0 0 0 4px var(--paper-bright); }

.ds-home-action {
  display: inline-flex;
  min-block-size: 44px;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  padding: var(--space-3) var(--space-4);
  border-radius: 6px;
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1.2;
  text-decoration: none;
}
.ds-home-action--primary {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--accent-text);
}
.ds-home-action--primary:hover, .ds-home-action--primary:focus-visible {
  background: var(--text);
  border-color: var(--text);
  color: var(--bg);
}
.ds-editorial-arrow {
  inline-size: 1.35rem;
  block-size: 1.35rem;
  flex: 0 0 auto;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.75;
  transition: transform 240ms cubic-bezier(0.16, 1, 0.3, 1);
}
a:is(:hover, :focus-visible) .ds-editorial-arrow, button:is(:hover, :focus-visible) .ds-editorial-arrow {
  transform: translate(4px, -4px);
}
.ds-home-action { box-sizing: border-box; font-family: var(--font-body); }
.ds-home-action:focus-visible { outline: 2px solid var(--ink); outline-offset: 4px; box-shadow: 0 0 0 4px var(--paper-bright); }

.ds-home-action {
  display: inline-flex;
  min-block-size: 44px;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  padding: var(--space-3) var(--space-4);
  border-radius: 6px;
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1.2;
  text-decoration: none;
}
.ds-home-action--secondary {
  border: 1px solid var(--border);
  color: var(--text);
  transition:
    border-color 160ms ease-out,
    color 160ms ease-out;
}
.ds-home-action--secondary:hover, .ds-home-action--secondary:focus-visible {
  border-color: var(--accent);
  color: var(--accent);
}
.ds-editorial-arrow {
  inline-size: 1.35rem;
  block-size: 1.35rem;
  flex: 0 0 auto;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.75;
  transition: transform 240ms cubic-bezier(0.16, 1, 0.3, 1);
}
a:is(:hover, :focus-visible) .ds-editorial-arrow, button:is(:hover, :focus-visible) .ds-editorial-arrow {
  transform: translate(4px, -4px);
}
.ds-home-action--secondary svg {
  inline-size: 1rem;
  block-size: 1rem;
  fill: none;
  stroke: currentColor;
  stroke-linecap: square;
  stroke-linejoin: miter;
  stroke-width: 1.5;
}
.ds-home-action { box-sizing: border-box; font-family: var(--font-body); }
.ds-home-action:focus-visible { outline: 2px solid var(--ink); outline-offset: 4px; box-shadow: 0 0 0 4px var(--paper-bright); }

.ds-site-header__navigation {
  display: flex;
  align-items: center;
  gap: clamp(var(--space-3), 1.6vw, var(--space-6));
  margin-inline-start: auto;
}
.ds-site-header__navigation a,
.ds-site-footer__navigation a {
  display: inline-flex;
  min-block-size: 44px;
  align-items: center;
  color: var(--ink-soft);
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  text-decoration: none;
  transition: color 160ms ease-out;
}
.ds-site-header__navigation a:hover,
.ds-site-header__navigation a:focus-visible,
.ds-site-footer__navigation a:hover,
.ds-site-footer__navigation a:focus-visible {
  color: var(--text);
}.ds-site-header__navigation a:focus-visible { outline: 2px solid var(--ink); outline-offset: 4px; box-shadow: 0 0 0 4px var(--paper-bright); }

.ds-accent-switcher {
  display: inline-flex;
  align-items: center;
  gap: 0;
  min-inline-size: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
.ds-accent-switcher label {
  position: relative;
  display: grid;
  inline-size: 44px;
  block-size: 44px;
  place-items: center;
  cursor: pointer;
}
.ds-accent-switcher input {
  position: absolute;
  inset: 0;
  z-index: 1;
  inline-size: 100%;
  block-size: 100%;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}
.ds-accent-switcher label > span:not(.ds-sr-only) {
  inline-size: 0.75rem;
  block-size: 0.75rem;
  border: 1px solid color-mix(in srgb, var(--ink) 34%, transparent);
  border-radius: 50%;
  background: var(--swatch);
  transition: transform 160ms ease-out;
}
.ds-accent-switcher input:checked + span {
  outline: 1px solid var(--ink);
  outline-offset: 3px;
  transform: scale(1.06);
}
.ds-accent-switcher input:focus-visible + span {
  outline: 2px solid var(--ink);
  outline-offset: 4px;
}

.ds-folio-label {
  display: flex;
  align-items: baseline;
  gap: 0.65rem;
  margin: 0;
  color: var(--ink-soft);
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}
.ds-folio-label__index {
  color: var(--accent-ink);
  background: var(--accent);
  padding: 0.22rem 0.35rem;
  border-radius: 999px;
}
.ds-folio-label__detail {
  margin-inline-start: auto;
  color: var(--text-muted);
  text-align: end;
}

.ds-method-spread__modules {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.75rem;
  padding: 0;
  margin: 0;
  list-style: none;
}
.ds-method-spread__modules > li {
  position: relative;
  overflow: hidden;
  background: var(--panel);
  border-radius: var(--radius-lg);
}
.ds-method-spread__modules > li:first-child { background: var(--accent); color: var(--accent-ink); }
.ds-method-spread__modules a {
  position: relative;
  display: flex;
  flex-direction: column;
  min-block-size: 25rem;
  padding: 2rem;
  text-decoration: none;
}
.ds-method-spread h3 { margin: 0; font-size: 1.5rem; font-weight: 500; letter-spacing: -0.03em; }
.ds-method-spread p { max-inline-size: 26ch; margin-block: 0.75rem 3rem; font-size: 0.875rem; line-height: 1.5; }
.ds-method-spread__index { display: flex; align-items: baseline; justify-content: space-between; margin-block-start: auto; font-size: clamp(4rem, 8vw, 7rem); letter-spacing: -0.07em; line-height: 1; }
.ds-method-spread__index .ds-editorial-arrow { align-self: end; margin-block-end: 0.5rem; }
.ds-method-spread__modules a:focus-visible {
  outline: 3px solid currentColor;
  outline-offset: -6px;
  border-radius: inherit;
  box-shadow: none;
}.ds-editorial-arrow {
  inline-size: 1.35rem;
  block-size: 1.35rem;
  flex: 0 0 auto;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.75;
  transition: transform 240ms cubic-bezier(0.16, 1, 0.3, 1);
}
a:is(:hover, :focus-visible) .ds-editorial-arrow,
button:is(:hover, :focus-visible) .ds-editorial-arrow {
  transform: translate(4px, -4px);
}.ds-method-spread { font-family: var(--font-body); } .ds-method-spread__modules { grid-template-columns: 1fr; } .ds-method-spread a:hover h3 { text-decoration: underline; }
